INSERT INTO [Movies] ([Movie_ID], [Movie_Name], [Release_Date], [End_Date], [Production_Company], [Director], [Cast], [Duration], [Genre], [Rating], [Language], [Country], [Synopsis], [Poster_URL], [Trailer_Link], [Status], [Created_By], [Created_At], [Updated_At]) VALUES
(1, N'Avengers: Endgame', '2024-08-01 00:00:00', '2026-12-31 00:00:00', N'Marvel Studios', N'Anthony Russo, Joe Russo', N'Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth', 181, N'Action, Adventure, Sci-Fi', N'PG-13', N'English', N'USA', N'Sau sự kiện Infinity War, các Avengers hợp sức để đánh bại Thanos và cứu vũ trụ khỏi sự hủy diệt.', N'https://image.tmdb.org/t/p/w500/or06FN3Dka5tukK1e9sl16pB3iy.jpg', N'https://www.youtube.com/watch?v=TcMBFSGVi1c', N'Now Showing', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(2, N'Spider-Man: No Way Home', '2024-08-10 00:00:00', '2026-12-31 00:00:00', N'Sony Pictures', N'Jon Watts', N'Tom Holland, Zendaya, Benedict Cumberbatch, Jamie Foxx', 148, N'Action, Adventure, Fantasy', N'PG-13', N'English', N'USA', N'Peter Parker nhờ Doctor Strange thực hiện phép thuật để xóa danh tính Spider-Man, nhưng mọi thứ trở nên hỗn loạn.', N'https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', N'https://www.youtube.com/watch?v=JfVOs4VSpmA', N'Now Showing', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(3, N'Inception', '2024-07-15 00:00:00', '2026-12-31 00:00:00', N'Warner Bros.', N'Christopher Nolan', N'Leonardo DiCaprio, Joseph Gordon-Levitt, Elliot Page, Tom Hardy', 148, N'Action, Sci-Fi, Thriller', N'PG-13', N'English', N'USA', N'Một tên trộm tài ba đi vào tâm trí người khác để đánh cắp bí mật nhận nhiệm vụ nguy hiểm nhất: trồng ý tưởng.', N'https://image.tmdb.org/t/p/w500/9gk7adHYeDvHkCSEqAvQNLV5Uge.jpg', N'https://www.youtube.com/watch?v=YoHD9XEInc0', N'Now Showing', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(4, N'Interstellar', '2026-09-01 00:00:00', '2026-11-30 00:00:00', N'Paramount Pictures', N'Christopher Nolan', N'Matthew McConaughey, Anne Hathaway, Jessica Chastain, Michael Caine', 169, N'Adventure, Drama, Sci-Fi', N'PG', N'English', N'USA', N'Nhóm phi hành gia đi qua lỗ sâu trong vũ trụ để tìm kiếm ngôi nhà mới cho nhân loại trước khi Trái Đất diệt vong.', N'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', N'https://www.youtube.com/watch?v=zSWdZVtXT7E', N'Coming Soon', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(5, N'The Dark Knight', '2026-10-01 00:00:00', '2026-12-31 00:00:00', N'Warner Bros.', N'Christopher Nolan', N'Christian Bale, Heath Ledger, Aaron Eckhart, Maggie Gyllenhaal', 152, N'Action, Crime, Drama', N'PG-13', N'English', N'USA', N'Batman phải đối mặt với Joker - tên tội phạm hỗn loạn muốn nhấn chìm Gotham City vào hỗn mang.', N'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', N'https://www.youtube.com/watch?v=EXeTwQWrcwY', N'Coming Soon', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(18, N'Mission: Impossible – Tối Hậu Thư', '2026-05-23 00:00:00', '2026-12-31 00:00:00', N'Paramount Pictures', N'Christopher McQuarrie', N'Tom Cruise, Hayley Atwell, Ving Rhames, Simon Pegg', 163, N'Action,Thriller', N'PG-13', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Ethan Hunt và nhóm IMF đối mặt với mối đe dọa nguy hiểm nhất từ trước đến nay — một thực thể AI bí ẩn có thể kiểm soát toàn bộ hệ thống vũ khí hạt nhân thế giới.', N'https://image.tmdb.org/t/p/w500/iKPsC9EFUafRP9SrUznI61getVP.jpg', N'https://www.youtube.com/watch?v=fsQgc9pCyDU', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(19, N'Thunderbolts*', '2026-05-02 00:00:00', '2026-12-31 00:00:00', N'Marvel Studios', N'Jake Schreier', N'Florence Pugh, Sebastian Stan, David Harbour, Wyatt Russell, Julia Louis-Dreyfus', 127, N'Action,Superhero,Adventure', N'PG-13', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Một nhóm nhân vật phản anh hùng bị ép buộc phải hợp tác để thực hiện một nhiệm vụ tự sát cho chính phủ.', N'https://image.tmdb.org/t/p/w500/hqcexYHbiTBfDIdDWxrxPtVndBX.jpg', N'https://www.youtube.com/watch?v=-sAOWhvheK8', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(20, N'Materialists', '2026-06-13 00:00:00', '2026-12-31 00:00:00', N'A24', N'Celine Song', N'Dakota Johnson, Chris Evans, Pedro Pascal', 100, N'Romance,Drama', N'PG-13', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Một người chuyên mai mối quyền lực ở New York bị kéo vào cuộc tình phức tạp giữa người cũ giàu có và người mới đơn giản.', N'https://image.tmdb.org/t/p/w500/eDo0pNruy0Qgj6BdTyHIR4cxHY8.jpg', N'https://www.youtube.com/watch?v=9gjeXsTsxqY', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(21, N'Jurassic World: Tái Sinh', '2026-07-02 00:00:00', '2026-12-31 00:00:00', N'Universal Pictures', N'Gareth Edwards', N'Scarlett Johansson, Jonathan Bailey, Mahershala Ali', 120, N'Adventure,Sci-Fi,Action', N'PG-13', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Năm năm sau sự kiện thảm khốc ở Dominion, một nhóm khoa học bí mật xâm nhập vào khu vực cách ly để thu thập ADN khủng long.', N'https://image.tmdb.org/t/p/w500/1RICxzeoNCAO5NpcRMIgg1XT6fm.jpg', N'https://www.youtube.com/watch?v=jan5CFWs9ic', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(22, N'F1: Tốc Độ Huyền Thoại', '2026-06-27 00:00:00', '2026-12-31 00:00:00', N'Apple Original Films', N'Joseph Kosinski', N'Brad Pitt, Damson Idris, Kerry Condon, Javier Bardem', 130, N'Action,Drama,Sport', N'PG-13', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Một tay đua huyền thoại quay trở lại đường đua F1 để hướng dẫn một tài năng trẻ, cùng nhau đối mặt với những đối thủ hùng mạnh và áp lực khổng lồ.', N'https://image.tmdb.org/t/p/w500/9PXZIUsSDh4alB80jheWX4fhZmy.jpg', N'https://www.youtube.com/watch?v=CT2_P2DZBR0', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(23, N'Bí Kíp Luyện Rồng: Live Action', '2026-06-13 00:00:00', '2026-12-31 00:00:00', N'DreamWorks Animation/Universal', N'Dean DeBlois', N'Mason Thames, Nico Parker, Gerard Butler', 110, N'Adventure,Family,Fantasy', N'PG', N'Tiếng Anh (Lồng tiếng Việt)', N'USA', N'Phiên bản người đóng của bộ phim hoạt hình kinh điển — chàng trai Viking Hiccup và chú rồng đêm không đuôi Toothless.', N'https://image.tmdb.org/t/p/w500/53dsJ3oEnBhTBVMigWJ9tkA5bzJ.jpg', N'https://www.youtube.com/watch?v=22w7z_lT6YM', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(24, N'Điểm Đến Cuối Cùng: Huyết Thống', '2026-05-16 00:00:00', '2026-12-31 00:00:00', N'New Line Cinema', N'Zach Lipovsky, Adam Stein', N'Kaitlyn Santa Juana, Teo Briones, Richard Harmon', 110, N'Horror,Thriller', N'R', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Một sinh viên đại học nhận ra cô có thể nhìn thấy cái chết trước khi nó xảy ra — giống như một tổ tiên của mình nhiều thập kỷ trước.', N'https://image.tmdb.org/t/p/w500/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', N'https://www.youtube.com/watch?v=xitSoRbHJ50', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(25, N'Kẻ Tội Đồ', '2026-04-18 00:00:00', '2026-12-31 00:00:00', N'Warner Bros. Pictures', N'Ryan Coogler', N'Michael B. Jordan, Hailee Steinfeld, Jack O''Connell', 137, N'Horror,Drama', N'R', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Hai anh em sinh đôi trở về miền Nam nước Mỹ sau Thế chiến I để xây dựng cuộc sống mới, nhưng thay vào đó lại đối mặt với một thứ kinh khủng hơn cả chiến tranh.', N'https://image.tmdb.org/t/p/w500/fWPgbnt2LSqkQ6cdQc0SZN9CpLm.jpg', N'https://www.youtube.com/watch?v=O98jSd24lmA', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(26, N'Superman', '2026-07-11 00:00:00', '2026-10-15 00:00:00', N'DC Studios/Warner Bros.', N'James Gunn', N'David Corenswet, Rachel Brosnahan, Nicholas Hoult, Edi Gathegi', 130, N'Action,Superhero,Adventure', N'PG-13', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Chương đầu tiên của Vũ trụ DC mới — Clark Kent đang học cách cân bằng di sản Kryptonian với bản sắc con người của mình khi đối mặt với Lex Luthor.', N'https://image.tmdb.org/t/p/w500/ldyfo0BKmz5rWtJJKCvwaNS4cJT.jpg', N'https://www.youtube.com/watch?v=Ox8ZLF6cGM0', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(27, N'Vũ Nữ Sát Thủ', '2026-06-06 00:00:00', '2026-12-31 00:00:00', N'Lionsgate', N'Len Wiseman', N'Ana de Armas, Keanu Reeves, Anjelica Huston, Ian McShane', 118, N'Action,Thriller', N'R', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Eve Macarro lớn lên trong Ruska Roma và trở thành một sát thủ để trả thù cho cái chết của cha mình.', N'https://image.tmdb.org/t/p/w500/2VUmvqsHb6cEtdfscEA6fqqVzLg.jpg', N'https://www.youtube.com/watch?v=0FSwsrFpkbw', N'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(28, N'Avatar: Lửa và Tro', '2026-12-19 00:00:00', NULL, N'20th Century Studios', N'James Cameron', N'Sam Worthington, Zoe Saldana, Sigourney Weaver, Kate Winslet', 180, N'Sci-Fi,Adventure,Action', N'PG-13', N'Tiếng Anh (Lồng tiếng Việt)', N'USA', N'Tiếp theo của Avatar: The Way of Water — gia đình Sully tiếp tục cuộc hành trình trên Pandora.', N'https://image.tmdb.org/t/p/w500/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', N'https://www.youtube.com/watch?v=ITmRYfeg4H0', N'Coming Soon', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(29, N'Black Panther: Chiến Dịch Mới', '2026-11-06 00:00:00', NULL, N'Marvel Studios', N'Denys Couch', N'Letitia Wright, Lupita Nyong''o, Winston Duke', 130, N'Superhero,Action,Adventure', N'PG-13', N'Tiếng Anh (Phụ đề Việt)', N'USA', N'Shuri tiếp tục gánh vác vai trò Black Panther trong một cuộc xung đột toàn cầu mới.', N'https://image.tmdb.org/t/p/w500/sv1xJUazXeYqALzczSZ3O6nkH75.jpg', N'https://www.youtube.com/watch?v=_Z3QKkl1WyM', N'Coming Soon', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04');
